import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        long[] v = new long[n];
        for (int i = 0; i < n; i++) v[i] = s.nextLong();
        int m = n / 2;
        long[] p = new long[2];
        Thread t1 = new Thread(() -> {
            long x = 0;
            for (int i = 0; i < m; i++) x += v[i];
            p[0] = x;
        });
        Thread t2 = new Thread(() -> {
            long x = 0;
            for (int i = m; i < n; i++) x += v[i];
            p[1] = x;
        });
        t1.start();
        t2.start();
        t1.join();
        t2.join();
        System.out.println(p[0] + p[1]);
    }
}
